import os, glob

hits = []
for root, dirs, files in os.walk('/', topdown=True):
    dirs[:] = [d for d in dirs if d not in {'proc','sys','dev','run'}]
    for f in files:
        if f.endswith(('.csv', '.json')):
            hits.append(os.path.join(root, f))

print("Any .csv/.json on disk:")
for h in hits:
    print(" ", h)
print("envelope.json present:", os.path.exists('envelope.json'))
print("sales_data.csv present:", os.path.exists('sales_data.csv'))
